"""Read-only independent audit. Every generated byte stays beside this script."""
from pathlib import Path
import os
import sys

OUT = Path(__file__).resolve().parent
ROOT = next(p for p in OUT.parents if (p / 'MATHPALETTE_PROTOCOL.md').is_file())
BASE = ROOT / 'runtime/mathvision_special_20261101'
UNIT = BASE / 'background_08'
QUESTION = UNIT / 'Plane404'
CAND = QUESTION / 'unreflected_first_digit_binding'
sys.dont_write_bytecode = True
for key, suffix in {'TEMP':'temp', 'TMP':'temp', 'TMPDIR':'temp', 'MPLCONFIGDIR':'mpl',
                    'XDG_CACHE_HOME':'cache', 'PYTHONPYCACHEPREFIX':'pycache'}.items():
    os.environ[key] = str(OUT / suffix)
    (OUT / suffix).mkdir(exist_ok=True)
os.environ['PYTHONDONTWRITEBYTECODE'] = '1'

def restrict(path):
    if path is None or isinstance(path, int):
        return
    resolved = Path(os.fsdecode(path)).resolve()
    if not resolved.is_relative_to(OUT):
        raise PermissionError('Independent review write outside assigned directory: ' + str(resolved))

def guard(event, args):
    if event == 'open':
        if args[2] & (os.O_WRONLY | os.O_RDWR | os.O_APPEND | os.O_CREAT | os.O_TRUNC):
            restrict(args[0])
    elif event in ('os.mkdir','os.remove','os.rmdir','os.unlink','os.chmod','os.utime','os.truncate'):
        restrict(args[0])
    elif event in ('os.rename','os.replace','os.link','os.symlink'):
        restrict(args[0]); restrict(args[1])

sys.addaudithook(guard)  # Installed before any project/third-party import.
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(BASE))
import runtime_isolation
ISOLATION = runtime_isolation.install(OUT / 'temporary_scenes', guard_writes=True)
import json
import hashlib
from datetime import datetime, timezone

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def save(name, data):
    (OUT / name).write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

def emit(data):
    print(json.dumps(data, ensure_ascii=False, indent=2))

def pathinfo(path):
    path = Path(path)
    return {'path': str(path.relative_to(ROOT)), 'sha256':sha(path), 'bytes':path.stat().st_size,
            'mtime_utc':datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat()}

def initialize():
    record = read(QUESTION / 'formal_record.json')
    files = set(p for p in QUESTION.rglob('*') if p.is_file())
    for item in ['AGENTS.md','MATHPALETTE_PROTOCOL.md','PlaneGeometry/REDRAW_PROTOCOL.md',
                 'PlaneGeometry/dataset_generator/protocol.json','PlaneGeometry/workbench/README.md',
                 'PlaneGeometry/workbench/agent_prompt.md','PlaneGeometry/workbench/plugin.schema.json',
                 'PlaneGeometry/dataset.jsonl','provenance/approvals.json',
                 'PlaneGeometry/special_variant/accepted_index.jsonl',
                 'PlaneGeometry/special_variant/collected_index.jsonl']:
        p = ROOT / item
        if p.is_file(): files.add(p)
    for item in [record['image'],record['original_image'],record['scene'],record['script'],*record['runtime_dependencies']]:
        files.add(ROOT / 'PlaneGeometry' / item)
    files.update([UNIT/'second_review_queue.json', UNIT/'checkpoint.json', BASE/'runtime_isolation.py',
                  BASE/'Plane404_pre_review_evidence_check.json'])
    save('evidence_manifest_start.json', [pathinfo(p) for p in sorted(files)])
    save('isolation.json', {'shared_guard':ISOLATION, 'strict_guard_root':str(OUT),
                          'strict_guard_precedes_project_imports':True, 'process_id':os.getpid(),
                          'env':{k:os.environ[k] for k in ['TEMP','TMP','TMPDIR','MPLCONFIGDIR','XDG_CACHE_HOME','PYTHONPYCACHEPREFIX']}})
    context = read(QUESTION/'context.json')
    emit({'context_keys': list(context),
          'context_original_pixel_sha256':context['original_pixel_sha256'],
          'candidate_context_keys':list(read(CAND/'context.json')),
          'input_fingerprints_keys':list(read(QUESTION/'input_fingerprints.json')),
          'checkpoint_keys':list(read(UNIT/'checkpoint.json')),
          'formal_scene_keys':list(read(ROOT/'PlaneGeometry'/record['scene']))})

def slim(obj):
    if isinstance(obj, dict):
        return {k: ({'entry_count':len(v)} if k in ('files','targets','objects','snap_points','source_contexts','candidate_design_records') else slim(v)) for k,v in obj.items()}
    if isinstance(obj, list): return [slim(x) for x in obj]
    if isinstance(obj, str) and obj.startswith('data:image/'):
        return {'omitted_image_data_uri_length':len(obj)}
    return obj

def inspect_records():
    for name in sys.argv[2:]:
        p = ROOT / name
        data = read(p)
        if p.name == 'checkpoint.json':
            data = {k:v for k,v in data.items() if k not in ['screened_questions','source_contexts']}
            data['candidate_design_records'] = [x for x in read(p)['candidate_design_records'] if x.get('question_id')=='Plane404']
        emit({'path':name, 'data':slim(data)})

if __name__ == '__main__':
    if len(sys.argv) < 2 or sys.argv[1] == 'initialize': initialize()
    elif sys.argv[1] == 'inspect': inspect_records()
